const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function projectileFootprintOwnershipPresentation(input, reducedMotion = false) { const footprint = clamp01(Math.max(input.bodyOverlap, input.laneProximity * .92)), floor = input.critical ? .78 : .42, trailCeiling = Math.max(floor, 1 - footprint * (input.critical ? .18 : .43)) * (reducedMotion ? .96 : 1); return { footprint, canonicalBodyScale: 1, trailCeiling, presentationOnly: true }; }
export function telegraphSafeLaneFootprintOwnershipPresentation(input, reducedFlash = false) { const overlap = clamp01(input.overlap), protectedOwners = (input.telegraphActive ? 1 : 0) + (input.safeLaneVisible ? 1 : 0), focus = clamp01(overlap + (input.critical ? .08 : 0)), base = protectedOwners >= 2 ? Math.max(.48, 1 - focus * .52) : protectedOwners === 1 ? Math.max(.58, 1 - focus * .36) : 1; return { footprint: focus, telegraphEdgeScale: 1, safeLaneScale: 1, secondaryCeiling: clamp01(base * (reducedFlash ? .96 : 1)), presentationOnly: true }; }
export function impactFootprintOwnershipPresentation(input, reducedFlash = false) { const footprint = clamp01(Math.max(input.heroProximity, input.safeLaneProximity * .96)), floor = input.critical ? .56 : .32, fillCeiling = Math.max(floor, 1 - footprint * (input.critical ? .3 : .68)) * (reducedFlash ? .96 : 1), secondaryCeiling = Math.max(input.critical ? .62 : .46, 1 - footprint * .46) * (reducedFlash ? .97 : 1); return { footprint, canonicalBodyScale: 1, fillCeiling, secondaryCeiling, presentationOnly: true }; }
export function specialistFootprintOwnershipPresentation(input, reducedMotion = false) { const footprint = clamp01(input.hazardPressure * .56 + input.crowd * .44), ownerWeight = input.owner === 'recovery' ? 1 : input.owner === 'locomotion' ? .72 : input.owner === 'hit' ? .64 : input.owner === 'attack' ? .46 : .38, floor = input.critical ? .72 : input.owner === 'recovery' ? .56 : .62, trailCeiling = Math.max(floor, 1 - footprint * (.32 + .18 * ownerWeight)) * (reducedMotion ? .96 : 1); return { footprint, canonicalBodyScale: 1, trailCeiling, presentationOnly: true }; }
export function sharedFootprintBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const pressure = clamp01(input.pressure), critical = clamp01(Math.max(0, input.criticalCount) / 3), reserve = (input.safeLaneVisible ? .08 : 0) + (input.bossTelegraphActive ? .08 : 0), secondaryCeiling = Math.max(.5, 1 - pressure * .34 - critical * .04 - reserve) * (reducedMotion ? .98 : 1) * (reducedFlash ? .97 : 1); return { pressure, criticalScale: 1, canonicalBodyScale: 1, bossTelegraphEdgeScale: 1, safeLaneScale: 1, secondaryCeiling: clamp01(secondaryCeiling), presentationOnly: true }; }
